/* Connected promotional journeys. Everything remains synthetic and session-local. */
const pClone=x=>JSON.parse(JSON.stringify(x));
const HOME_KEYS=['documents','objects','rooms','contacts','tasks','expenses','history','works','shares'];
const P={ownerArchives:{},generations:{roma:0,tigli:0},newOwnerPending:{},current:'roma',activeHome:'roma',homes:{},gifts:[],publications:[],invitations:[],links:{},issues:[],events:[],counter:100,selectedDossier:'Anteprima',proposalDone:[],team:{agency:[{name:'Giulia Demo',role:'Responsabile'}],admin:[{name:'Studio Verdi',role:'Responsabile'}]},brand:{agency:'Agenzia Aurora',admin:'Studio Verdi'},properties:[]};
function pSeed(id,name,city){return {id,name,city,unit:id==='roma'?'Scala A · Interno 12':'Scala unica · Interno 4',building:id==='roma'?'Condominio Roma':'Condominio dei Tigli',active:false,requested:[],dossier:[],docs:[{id:id+'-plan',name:'Planimetria della casa',present:true,reviewed:true,allowed:true,private:false,version:1,source:'Proprietario · raccolta per il fascicolo'},{id:id+'-ape',name:'APE',present:false,reviewed:false,allowed:true,private:false,version:1,source:'Professionista · raccolta per il fascicolo'},{id:id+'-book',name:'Libretto caldaia',present:true,reviewed:false,allowed:true,private:false,version:1,source:'Tecnico · raccolta per il fascicolo'},{id:id+'-personal',name:'Documento personale del venditore',present:true,reviewed:true,allowed:false,private:true,version:1,source:'Venditore · documento riservato'}],assets:[{id:id+'-boiler',name:'Caldaia della casa',room:'Locale tecnico',doc:id+'-book',type:'Impianto'}],technical:[{id:id+'-lift',name:'Ascensore',note:'Rapporto controllo disponibile',date:'2026-12-01',doc:'Rapporto ascensore',version:1,shared:true},{id:id+'-heating',name:'Centrale termica',note:'Libretto tecnico da rivedere',date:'2026-11-15',doc:'Libretto centrale termica',version:1,shared:true},{id:id+'-internal',name:'Appunti interni dello studio',note:'Solo studio',date:'',doc:'Nota interna',version:1,shared:false}],budget:18000};}
P.properties=[pSeed('roma','Via Roma 12','Milano'),pSeed('tigli','Via dei Tigli 8','Torino')];
P.homes.roma=Object.fromEntries(HOME_KEYS.map(k=>[k,V5[k]]));
P.homes.tigli=Object.fromEntries(HOME_KEYS.map(k=>[k,k==='rooms'?['Cucina','Soggiorno']:[]]));
const pProperty=()=>P.properties.find(p=>p.id===P.current);
const pId=()=>String(++P.counter);
const pButton=(label,a,light=false)=>button(label,'p:'+a,light);
const pRow=(title,sub,a,label='Apri',icon='▤')=>row(title,sub,a?'p:'+a:null,label,icon);
const pEmpty=t=>`<p class="p-empty">${esc(t)}</p>`;
const pStatus=t=>`<span class="p-state">${esc(t)}</span>`;
function pLog(title,from,to,property=P.current){P.events.push({id:pId(),property,title,from,to});}
function pSelect(id){const p=P.properties.find(x=>x.id===id);if(!p)return;P.homes[P.activeHome]=Object.fromEntries(HOME_KEYS.map(k=>[k,V5[k]]));if(!P.homes[id])P.homes[id]=Object.fromEntries(HOME_KEYS.map(k=>[k,k==='rooms'?['Cucina','Soggiorno']:[]]));HOME_KEYS.forEach(k=>V5[k]=P.homes[id][k]);P.activeHome=id;P.current=id;state.selected=p.name;V5.workflow='Tutti';V5.family='Tutte le famiglie';V5.query='';V5.room='Tutte le stanze';V5.year='Tutti';V5.objectQuery='';V5.expenseQuery='';V5.contactQuery='';V5.roomQuery='';V5.objectState='Attivi';}
function pSwitch(role,page){state.tour=false;V5.mobileMenu=false;go(role,page||roles[role].nav[0]);}
function pModal(title,body,actions){vModal(title,body,actions||pButton('Chiudi','close',true));}
function pValue(id){return $('#'+id)?.value?.trim()||'';}
function pValidEmail(email){return /^\S+@\S+\.\S+$/.test(email);}
function pFormError(text){vError(text);}
function pFlow(){return `<section class="p-flow" aria-label="Passaggio delle informazioni"><div class="${state.role==='agency'?'current':''}"><span>01 · Agenzia</span><strong>Prepara la memoria</strong>${pButton('Fascicolo →','switch:agency:Checklist',true)}</div><i>→</i><div class="${state.role==='home'?'current':''}"><span>02 · Home</span><strong>Accetta e conserva</strong>${pButton('Consegne ricevute →','switch:home:Consegne ricevute',true)}</div><i>←</i><div class="${state.role==='admin'?'current':''}"><span>03 · Amministratore</span><strong>Aggiorna le parti comuni</strong>${pButton('Pubblicazioni →','switch:admin:Pubblicazioni',true)}</div></section>`;}
function pBenefit(title,text,next,label='Prossimo passo →'){return `<div class="banner p-benefit"><div><div class="eyebrow">${state.role==='agency'?'Dall’incarico alle chiavi':state.role==='admin'?'Dall’edificio alla casa':'Una casa, informazioni collegate'}</div><h3>${title}</h3><p>${text}</p></div>${next?pButton(label,next):''}</div>`;}
function pPortfolio(){return card(state.role==='agency'?'I tuoi fascicoli':'I tuoi edifici',P.properties.filter(p=>!p.giftHome).map(p=>pRow(p.name,p.city+' · '+p.unit+' · '+(state.role==='agency'?(p.active?'Fascicolo attivo':'Scheda preliminare'):'Memoria tecnica disponibile'),'select:'+p.id,'Apri','⌂')).join(''))+pButton(state.role==='agency'?'Nuovo fascicolo':'Nuovo edificio','property-new',true);}
function pChecklist(){const p=pProperty();return pBenefit('Sai subito cosa manca.','Raccogli i documenti, rivedi le informazioni e prepara il dossier. Ricevuto non significa verificato.','request','Prepara richiesta')+`<div class="p-inline">${pStatus(p.active?'Fascicolo attivo · demo':'Scheda preliminare')}${p.active?'':pButton('Attiva fascicolo · demo','activate',true)}</div>`+card('Documenti · '+esc(p.name),p.docs.map(d=>`<div class="row"><div class="row-icon">▤</div><div class="rowbody"><strong>${esc(d.name)}</strong><p>${esc(d.source)} · v${d.version}</p>${pStatus(!d.present?p.requested.includes(d.id)?'Richiesto':'Mancante':d.private?'Riservato · escluso dalle consegne':d.reviewed?'Esaminato · non certificato':'Ricevuto · da rivedere')}</div>${d.present?pButton('Apri','agency-document:'+d.id,true):pButton('Simula ricezione','receive:'+d.id,true)}</div>`).join(''))+`<div class="actions">${pButton('Prepara dossier →','switch:agency:Dossier acquirente')}${pButton('Aggiungi documento di esempio','agency-add',true)}</div>`;}
function pAgencyDoc(id){const p=pProperty(),d=p.docs.find(x=>x.id===id);if(!d)return;pModal(d.name,`<p>Fonte: ${esc(d.source)} · versione ${d.version}</p><div class="v5-original"><h3>${esc(d.name)}</h3><p>Facsimile per ${esc(p.name)}. Nessun file di cliente caricato.</p></div><p>${d.private?'Documento personale: escluso da dossier e Home Gift.':'Disponibilità e correttezza sono cose diverse. La verifica tecnica resta al professionista.'}</p>${!d.reviewed&&!d.private?'<p><strong>Proposta dimostrativa:</strong> collega il libretto alla caldaia. Nessuna data di garanzia o scadenza normativa dedotta.</p>':''}`,(!d.reviewed&&!d.private?pButton('Segna come esaminato','agency-review:'+id):'')+pButton('Torna alla checklist','close',true));}
function pDossier(){const p=pProperty(),available=p.docs.filter(d=>d.present&&d.allowed&&!d.private);return pBenefit('Condividi il contesto giusto.','Anteprima divulgabile e dossier riservato hanno selezioni distinte. Nessun documento viene mostrato automaticamente.','dossier-preview','Anteprima dossier')+vTabs('Livello dossier',['Anteprima','Riservato'],P.selectedDossier,'partnerDossier').replaceAll('v5:tab:partnerDossier:','p:dossier-mode:')+card('Contenuti · '+P.selectedDossier,`<p>${P.selectedDossier==='Anteprima'?'Scheda immobile senza originali riservati.':'Seleziona i documenti ricevuti ed esaminati, dopo aver verificato i diritti.'}</p>${available.map(d=>`<label class="check"><input type="checkbox" data-dossier="${d.id}" ${p.dossier.includes(d.id)?'checked':''} ${P.selectedDossier==='Anteprima'||!d.reviewed?'disabled':''}><span>${esc(d.name)}<small>${d.reviewed?'Esaminato · v'+d.version:'Da rivedere prima della condivisione'}</small></span></label>`).join('')}<p class="tiny">I documenti personali del venditore restano esclusi.</p>${pButton('Salva selezione e apri anteprima','dossier-save')}`)+pButton('Prepara Home Gift →','switch:agency:Home Gift',true);}
function pGiftPage(){const p=pProperty(),gifts=P.gifts.filter(g=>g.property===p.id);return pBenefit('Le chiavi, con la memoria della casa.','Una consegna selezionata di documenti e schede. Il nuovo proprietario la accetta nella propria Home.','gift-start','Prepara Home Gift')+card('Le consegne del fascicolo',gifts.map(g=>pRow(g.email,g.status+' · '+g.documents.length+' documenti · '+g.assets.length+' schede','gift-detail:'+g.id,'Apri','↗')).join('')||pEmpty('Nessuna consegna ancora preparata.'))+pFlow();}
function pGiftStart(){const p=pProperty(),docs=p.docs.filter(d=>d.present&&d.reviewed&&d.allowed&&!d.private);pModal('Scegli la memoria da consegnare',`<p>${esc(p.name)} · Seleziona solo ciò che puoi consegnare.</p><details><summary>Documenti condivisi · ${docs.length} selezionati</summary>${docs.map(d=>`<label class="check"><input type="checkbox" data-gift-doc="${d.id}" checked><span>${esc(d.name)}<small>Versione ${d.version} · ${esc(d.source)}</small></span></label>`).join('')||pEmpty('Rivedi almeno un documento nella checklist prima di consegnarlo.')}</details><details><summary>Schede degli impianti · scegli cosa includere</summary>${p.assets.map(a=>`<label class="check"><input type="checkbox" data-gift-asset="${a.id}" ${docs.some(d=>d.id===a.doc)?'checked':'disabled'}><span>${esc(a.name)}<small>Richiede il documento fonte selezionato. Nessuna spesa o contatto privato incluso.</small></span></label>`).join('')}</details>${vField('Nome della casa da consegnare','p-home-name',p.name)+vField('Email del nuovo proprietario (fittizia)','p-email','proprietario@example.test','email')}<label class="check"><input id="p-rights" type="checkbox"><span>Ho controllato selezione, destinatario e diritti nella demo.</span></label><p class="tiny">Un invito non crea un account e non dà accesso alla Home privata all’agenzia.</p>`,pButton('Rivedi manifesto →','gift-preview'));}
function pPrepareGift(documentIds,assetIds,email,rights){const p=pProperty();if(!rights||!pValidEmail(email))throw Error('Controlla destinatario e diritti di consegna.');const documents=documentIds.map(id=>p.docs.find(d=>d.id===id));if(!documents.length||documents.some(d=>!d||!d.present||!d.reviewed||!d.allowed||d.private))throw Error('Seleziona solo documenti ricevuti, esaminati e autorizzati.');const assets=assetIds.map(id=>p.assets.find(a=>a.id===id));if(assets.some(a=>!a||!documentIds.includes(a.doc)))throw Error('Seleziona anche il documento fonte delle schede scelte.');return {id:pId(),property:p.id,generation:P.generations[p.id]||0,email,sender:P.brand.agency,status:'Invito predisposto',documents:pClone(documents),assets:pClone(assets),accepted:false};}
function pAcceptGift(id){const gift=P.gifts.find(g=>g.id===id);if(!gift||(gift.generation||0)!==(P.generations[gift.property]||0)||gift.status==='Revocato'||gift.status==='Scaduto')throw Error('Questa consegna non è disponibile per la casa selezionata.');if(gift.accepted){pSelect(gift.homeId);return false;}pCreateGiftHome(gift);P.properties.find(p=>p.id===gift.homeId).homeAvailable=true;pSelect(gift.homeId);gift.documents.forEach(d=>{const docId='gift-'+gift.id+'-'+d.id;if(!V5.documents.some(x=>x.id===docId))V5.documents.push({id:docId,name:d.name,family:d.name.includes('Planimetria')?'Catasto e pratiche edilizie':'Energia e impianti',status:'Completato',object:'',personal:true,origin:'Home Gift · '+(gift.sender||P.brand.agency),sourceVersion:d.version,gift:gift.id});});gift.assets.forEach(a=>{const oid='gift-'+gift.id+'-'+a.id,doc='gift-'+gift.id+'-'+a.doc;if(!V5.objects.some(o=>o.id===oid))V5.objects.push({id:oid,name:a.name,brand:'Da completare',model:'Da completare',room:a.room,type:a.type,archived:false,warranty:'Da verificare',doc,documents:[doc],cost:0});if(!V5.rooms.includes(a.room))V5.rooms.push(a.room);});V5.history.push({id:pId(),title:'Home Gift accettata',date:'2026-10-24',doc:'',kind:'Consegna selezionata'});gift.accepted=true;gift.status='Accettato';pLog('Home Gift accettata: '+gift.documents.length+' documenti','Agenzia','Home',gift.property);return true;}
function pGiftDetail(id){const g=P.gifts.find(x=>x.id===id);if(!g)return;pModal('Manifesto Home Gift',`<p><strong>${esc(g.homeName||P.properties.find(p=>p.id===g.property)?.name)}</strong></p><p>${esc(g.email)} · ${esc(g.status)}</p>${g.documents.map(d=>pRow(d.name,'v'+d.version+' · '+d.source,null)).join('')}${g.assets.map(a=>pRow(a.name,'Scheda selezionata · fonte inclusa',null)).join('')}<p class="tiny">Esclusi: originali personali, spese e contatti privati. Nessun invio reale.</p>`,pButton('Vedi la consegna in Home →','gift-home:'+id)+(g.accepted?'':pButton('Revoca invito demo','gift-revoke:'+id,true)));}
function pTechnical(){const p=pProperty();return pBenefit('Ogni impianto, con la sua fonte.','Documenti, interventi e attenzioni restano collegati all’edificio. Scegli dopo cosa pubblicare.','admin-import','Aggiungi documento')+card('Memoria tecnica · '+esc(p.building),p.technical.map(t=>pRow(t.name,t.note+' · '+(t.shared?'Pubblicabile su scelta':'Solo studio'),'technical:'+t.id,'Apri','▥')).join(''))+pButton('Seleziona cosa pubblicare →','switch:admin:Pubblicazioni',true);}
function pTechnicalDetail(id){const t=pProperty().technical.find(x=>x.id===id);if(!t)return;pModal(t.name,`<p>${esc(pProperty().building)} · Fonte: ${esc(t.doc)} · v${t.version}</p><p>${esc(t.note)}</p><p>Attenzione: ${vDate(t.date)} · data dimostrativa inserita dallo studio.</p><p>${t.shared?'Archiviato nello studio, non pubblicato automaticamente.':'Documento interno: non selezionabile per le Home.'}</p>`,pButton('Rivedi dati e data','technical-edit:'+id)+pButton('Vedi pubblicazioni','switch:admin:Pubblicazioni',true));}
function pPublishPage(){const p=pProperty();return pBenefit('Una selezione. Un aggiornamento chiaro.','La memoria comune arriva solo alle unità collegate. La Home privata resta sotto il controllo del proprietario.','publish-start','Prepara pubblicazione')+card('Pubblicazioni dell’edificio',P.publications.filter(x=>x.property===p.id).map(x=>pRow(x.title,'v'+x.version+' · '+x.status+' · '+p.unit,'publication:'+x.id,'Apri','▥')).join('')||pEmpty('Nessuna pubblicazione: i documenti sono ancora interni allo studio.'))+pFlow();}
function pPublishStart(){const p=pProperty();pModal('Scegli contenuti e destinatari',`<p>${esc(p.building)} · ${esc(p.unit)}</p><label for="p-tech">Documento tecnico</label><select id="p-tech">${p.technical.filter(t=>t.shared).map(t=>`<option value="${t.id}">${esc(t.doc)} · v${t.version}</option>`).join('')}</select>${vField('Titolo dell’aggiornamento','p-title','Aggiornamento ascensore')}<label for="p-note">Messaggio per il proprietario</label><textarea id="p-note">Il documento aggiornato è disponibile nella memoria comune.</textarea><label class="check"><input id="p-proposal" type="checkbox"><span>Proponi anche un promemoria personale, da rivedere in Home.</span></label><label class="check"><input id="p-rights" type="checkbox"><span>Ho verificato contenuto e destinatari della simulazione.</span></label><p class="tiny">Gli appunti interni non sono pubblicabili. Nessun dato privato viene sovrascritto.</p>`,pButton('Anteprima pubblicazione →','publish-preview'));}
function pPublish(technicalId,title,note,rights,proposal=false){const p=pProperty(),t=p.technical.find(x=>x.id===technicalId);if(!rights||!t||!t.shared||!title.trim())throw Error('Controlla documento pubblicabile, titolo e destinatari.');let pub=P.publications.find(x=>x.property===p.id&&x.technical===t.id);if(pub){pub.version++;Object.assign(pub,{title,note,status:'Pubblicato',proposal,sourceVersion:t.version,sender:P.brand.admin});}else{pub={id:pId(),property:p.id,technical:t.id,title,note,sender:P.brand.admin,doc:t.doc,sourceVersion:t.version,version:1,status:'Pubblicato',proposal};P.publications.push(pub);}pLog('Pubblicazione v'+pub.version+': '+title,'Amministratore','Home');return pub;}
function pVisiblePublications(){return P.links[P.activeHome]?.status==='Collegato'?P.publications.filter(x=>x.property===P.activeHome&&x.status==='Pubblicato'):[];}
function pPublication(id){const x=P.publications.find(p=>p.id===id);if(!x)return;pModal(x.title,`<p>${esc(P.brand.admin)} · Pubblicazione v${x.version} · ${esc(x.status)}</p><p>Documento: ${esc(x.doc)} · fonte v${x.sourceVersion}</p><p>${esc(x.note)}</p><p>Destinatari: ${esc(P.properties.find(p=>p.id===x.property).unit)}</p>`,pButton('Vedi come proprietario →','publication-home:'+id)+(state.role==='admin'?pButton('Ritira pubblicazione','publication-revoke:'+id,true):''));}
function pUnits(){const p=pProperty(),link=P.links[p.id];return pBenefit('La persona giusta, nell’unità giusta.','Predisponi l’invito. Il proprietario lo accetta in Home; la verifica dei diritti resta una fase distinta.','unit-invite','Prepara invito')+card('Unità dimostrativa',pRow(p.unit,link?.status||'Non collegata','unit-invite','Invita','⌂')+pRow('Cambio proprietario','Efficacia e accessi da riesaminare','ownership','Simula','↗'))+card('Inviti predisposti',P.invitations.filter(i=>i.property===p.id).map(i=>pRow(i.email,i.status,'invitation:'+i.id,'Apri')).join('')||pEmpty('Nessun invito.'));}
function pInvite(email,rights){if(!pValidEmail(email)||!rights)throw Error('Indica un destinatario valido e verifica unità e diritti.');const inv={id:pId(),property:P.current,email,status:'Da accettare',newOwner:!!P.newOwnerPending[P.current]};P.invitations.push(inv);pLog('Invito al collegamento unità predisposto','Amministratore','Home');return inv;}
function pAcceptInvitation(id){const i=P.invitations.find(x=>x.id===id);if(!i||i.property!==P.activeHome||i.status!=='Da accettare')throw Error('Invito non disponibile per questa unità.');if(i.newOwner&&P.newOwnerPending[i.property]){P.ownerArchives[i.property]=pClone(Object.fromEntries(HOME_KEYS.map(k=>[k,V5[k]])));HOME_KEYS.forEach(k=>V5[k]=k==='rooms'?['Cucina','Soggiorno']:[]);P.homes[i.property]=Object.fromEntries(HOME_KEYS.map(k=>[k,V5[k]]));delete P.newOwnerPending[i.property];}i.status='Accettato';P.links[i.property]={status:'Collegato',invitation:i.id,email:i.email};pLog('Collegamento al condominio accettato','Home','Amministratore',i.property);}
function pHomeInbox(){const gifts=P.gifts.filter(g=>(g.generation||0)===(P.generations[g.property]||0)),invitations=P.invitations.filter(i=>i.property===P.activeHome);return pBenefit('Le informazioni arrivano. Tu decidi.','Accetta una Home Gift o collega la tua unità al condominio. Nessun accesso alla tua memoria privata viene concesso ai Partner.')+card('Home Gift dall’agenzia',gifts.map(g=>pRow((g.homeName||P.properties.find(p=>p.id===g.property)?.name)+' · '+g.documents.length+' documenti',P.brand.agency+' · '+g.status,'gift-inbox:'+g.id,g.accepted?'Riepilogo':'Rivedi','↗')).join('')||pEmpty('Ancora nessuna Gift. Preparala dal profilo Agenzia.'))+card('Inviti dal tuo amministratore',invitations.map(i=>pRow(pProperty().unit,P.brand.admin+' · '+i.status,'invitation:'+i.id,'Rivedi','▥')).join('')||pEmpty('Nessun invito al condominio.'))+pFlow();}
function pCondo(){const linked=P.links[P.activeHome]?.status==='Collegato',visible=pVisiblePublications();return pBenefit(linked?'La tua casa, collegata al condominio.':'La memoria comune inizia da un collegamento.',linked?'Fonte, versione e aggiornamenti dello studio sono distinguibili dai tuoi dati personali.':'Accetta l’invito dell’amministratore per vedere i contenuti pubblicati per la tua unità.',linked?'issue-start':'switch:home:Consegne ricevute',linked?'Segnala un problema':'Vedi inviti →')+card('Documenti e aggiornamenti comuni',visible.map(x=>pRow(x.title,x.doc+' · '+P.brand.admin+' · v'+x.version,'publication:'+x.id,'Consulta','▥')).join('')||pEmpty(linked?'Nessuna pubblicazione per la tua unità.':'Unità non ancora collegata.'))+card('Da rivedere nella tua Home',visible.filter(x=>x.proposal&&!P.proposalDone.includes(x.id+':'+x.version)).map(x=>pRow('Promemoria proposto dallo studio',x.title+' · non ancora nelle tue attività','proposal:'+x.id,'Rivedi','◷')).join('')||pEmpty('Nessuna proposta in attesa.'))+card('Le tue segnalazioni',P.issues.filter(i=>i.property===P.activeHome).map(i=>pRow(i.title,i.status+' · '+i.reply,'issue:'+i.id,'Apri','◷')).join('')||pEmpty('Nessuna segnalazione inviata nella demo.'));}
function pIssues(){return pBenefit('Una richiesta con il suo contesto.','Il proprietario vede gli aggiornamenti. Tu ritrovi edificio, problema e stato della segnalazione.','switch:home:Condominio','Prova dal profilo Home →')+card('Segnalazioni · '+esc(pProperty().building),P.issues.filter(i=>i.property===P.current).map(i=>pRow(i.title,pProperty().unit+' · '+i.status,'issue:'+i.id,'Gestisci','◷')).join('')||pEmpty('Nessuna segnalazione. Prova a crearne una dalla Home collegata.'));}
function pIssueStart(){if(P.links[P.activeHome]?.status!=='Collegato'){pModal('Collega prima l’unità','<p>Accetta l’invito dello studio per predisporre una segnalazione della tua unità.</p>',pButton('Vedi inviti','switch:home:Consegne ricevute'));return}pModal('Segnala un problema',vField('Cosa hai notato?','p-title')+'<label for="p-note">Dettagli</label><textarea id="p-note" placeholder="Es. illuminazione dell’ingresso"></textarea><p class="tiny">Solo una simulazione: nessun messaggio verrà inviato.</p>',pButton('Predisponi segnalazione','issue-save'));}
function pIssue(id){const i=P.issues.find(x=>x.id===id);if(!i)return;pModal(i.title,`<p>${esc(i.detail)}</p><p>${esc(pProperty().unit)} · ${esc(i.status)}</p>${state.role==='admin'?vSelect('Stato','p-issue-status',['Ricevuta','In valutazione','Intervento programmato','Risolta'],i.status)+'<label for="p-reply">Aggiornamento per il proprietario</label><textarea id="p-reply">'+esc(i.reply)+'</textarea>':'<p>Studio: '+esc(i.reply||'In attesa di un aggiornamento')+'</p>'}`,state.role==='admin'?pButton('Aggiorna nella demo','issue-update:'+id):pButton('Chiudi','close',true));}
function pTeam(){return card('Le persone del tuo studio',P.team[state.role].map(m=>pRow(m.name,m.role,null,'','♧')).join('')+pButton('Aggiungi collaboratore demo','team-new',true))+card('Il tuo marchio',`<p>${esc(P.brand[state.role])} · compare nelle consegne e nelle pubblicazioni.</p>${pButton('Personalizza nome','brand',true)}`)+card('Import da file compatibili','<p>Esplora la revisione dei dati prima di aggiungerli. Nessun CRM o gestionale è connesso.</p>'+pButton('Prova import di esempio','import-tool',true));}
function pHandoffs(){return pFlow()+card('Cosa passa, e cosa resta privato',`<div class="p-transfer-rule"><strong>Agenzia → Home</strong><p>Solo la selezione del manifesto, dopo l’accettazione. Nessun accesso dell’agenzia ai tuoi documenti personali.</p></div><div class="p-transfer-rule"><strong>Amministratore → Home</strong><p>Contenuti comuni pubblicati per l’unità collegata. Le modifiche personali restano proposte da rivedere.</p></div><div class="p-transfer-rule"><strong>Home → Amministratore</strong><p>La segnalazione del proprietario, con il suo contesto. Il resto della Home resta privato.</p></div>`)+card('La traccia dei passaggi',P.events.filter(e=>e.property===P.current).map(e=>pRow(e.title,e.from+' → '+e.to,null,'','↗')).join('')||pEmpty('Esplora un percorso: i passaggi compariranno qui.'));}
const partnerBasePage=pageContent,partnerBaseWorkspace=workspace,partnerBaseDocuments=vDocuments;
roles.home.nav.splice(roles.home.nav.indexOf('Condivisioni')+1,0,'Consegne ricevute');
for(const r of Object.values(roles))r.nav.push('Passaggi tra profili');
roles.agency.journey=['Fascicoli','Checklist','Dossier acquirente','Home Gift','Passaggi tra profili'];
roles.admin.journey=['Edifici','Impianti e memoria','Unità e accessi','Pubblicazioni','Segnalazioni','Passaggi tra profili'];
roles.home.journey=['Casa','Consegne ricevute','Documenti','Condominio','Passaggi tra profili'];
pageContent=function(){const p=pProperty(),page=state.page;if(page==='Passaggi tra profili')return pHandoffs();if(state.role==='home'){if(page==='Consegne ricevute')return pHomeInbox();if(page==='Condominio')return pCondo();let html=partnerBasePage();if(page==='Casa')html=pBenefit('La tua memoria, con le informazioni che scegli.',P.gifts.some(g=>g.property===P.current&&!g.accepted)?'Hai una Home Gift da rivedere.':'Ritrova le consegne dell’agenzia e gli aggiornamenti dello studio.','switch:home:Consegne ricevute','Vedi consegne →')+html;return html;}if(page==='Panoramica')return pBenefit(state.role==='agency'?'Ogni fascicolo, pronto al passo successivo.':'Ogni edificio, con una memoria consultabile.',state.role==='agency'?'Raccogli, rivedi e consegna ciò che serve al nuovo proprietario.':'Collega impianti, documenti e aggiornamenti per le unità autorizzate.',state.role==='agency'?'switch:agency:Fascicoli':'switch:admin:Edifici')+metrics(state.role==='agency'?[['Fascicoli',P.properties.filter(p=>!p.giftHome).length,'Esempi separati'],['Documenti da rivedere',p.docs.filter(d=>d.present&&!d.reviewed).length,p.name],['Gift accettate',P.gifts.filter(g=>g.accepted&&g.property===p.id).length,'Dopo una scelta in Home']]:[['Edifici',P.properties.filter(p=>!p.giftHome).length,'Portafoglio dimostrativo'],['Unità collegata',P.links[p.id]?.status==='Collegato'?'Sì':'Da collegare',p.unit],['Pubblicazioni',P.publications.filter(x=>x.property===p.id&&x.status==='Pubblicato').length,'Selezionate dallo studio']])+pPortfolio()+pFlow();if(page==='Fascicoli'||page==='Edifici')return pPortfolio();if(page==='Checklist')return pChecklist();if(page==='Dossier acquirente')return pDossier();if(page==='Home Gift')return pGiftPage();if(page==='Impianti e memoria')return pTechnical();if(page==='Scadenze')return card('Attenzioni degli impianti comuni',p.technical.filter(t=>t.date).map(t=>pRow(t.name,vDate(t.date)+' · data dimostrativa inserita dallo studio','technical:'+t.id,'Apri','◷')).join(''))+pButton('Apri memoria tecnica','switch:admin:Impianti e memoria',true);if(page==='Budget e previsioni')return '<div class="v5-concept"><strong>Scenario dimostrativo, non preventivo</strong><p>Pianifica un’ipotesi. Nessun riparto millesimale o contabilità reale.</p></div>'+forecast(true);if(page==='Pubblicazioni')return pPublishPage();if(page==='Unità e accessi')return pUnits();if(page==='Segnalazioni')return pIssues();if(page==='Team e strumenti')return pTeam();return partnerBasePage();};
vDocuments=function(){let html=partnerBaseDocuments();const gifts=V5.documents.filter(d=>d.gift),pubs=pVisiblePublications();if(gifts.length)html+=card('Provenienza Home Gift',gifts.map(d=>pRow(d.name,d.origin+' · fonte v'+d.sourceVersion,'home-document:'+d.id,'Apri')).join(''));if(pubs.length)html+=card('Dal condominio · memoria comune',pubs.map(x=>pRow(x.doc,P.brand.admin+' · pubblicazione v'+x.version,'publication:'+x.id,'Consulta','▥')).join(''));return html;};
workspace=function(){let html=partnerBaseWorkspace();if(['Condominio','Consegne ricevute','Passaggi tra profili'].includes(state.page))html=html.replace('La stessa organizzazione della V5, con esempi da esplorare.','Una vista semplice sui passaggi che scegli.');if(state.role!=='home'){html=html.replace('</select>','</select><button class="v5-mobile-menu" aria-expanded="'+!!V5.mobileMenu+'" data-action="v5:mobile-nav">'+(V5.mobileMenu?'Chiudi menu':'Menu completo')+'</button>');if(V5.mobileMenu)html=html.replace('class="sidebar"','class="sidebar expanded"');}const selector=`<label class="p-context"><span>${state.role==='home'?'Le mie case':state.role==='admin'?'Edificio e unità':'Immobile dimostrativo'}</span><select id="p-property" aria-label="${state.role==='home'?'Le mie case':'Immobile dimostrativo'}">${P.properties.filter(p=>state.role==='home'?p.homeAvailable!==false:!p.giftHome).map(p=>`<option value="${p.id}" ${p.id===P.current?'selected':''}>${esc(p.name)} · ${esc(p.city)}</option>`).join('')}</select></label>`;html=html.replace('<div class="toolbar">','<div class="p-context-bar">'+selector+pButton('Vedi i passaggi ↗','switch:'+state.role+':Passaggi tra profili',true)+'</div><div class="toolbar">');if(state.role!=='home')html=html.replace('<div class="pagehead">','<div class="p-concept-note">Demo Partner navigabile · visione di prodotto, servizi reali non attivi</div><div class="pagehead">');html=html.replaceAll('undefined &nbsp;','↗ &nbsp;');html=html.replace('Home allineata ai percorsi V5 del 24 ottobre 2026 · Dati e operazioni simulati. Partner e anteprime sono concept distinti.','Tre percorsi collegati con dati fittizi · Nessuna email o modifica all’app reale · Stato della sola sessione demo.');return html;};
function pAction(a,args){const id=args.join(':'),p=pProperty();switch(a){
case'close':close();break;
case'switch':close();pSwitch(args[0],args.slice(1).join(':'));break;
case'select':pSelect(id);go(state.role,state.role==='agency'?'Checklist':'Impianti e memoria');break;
case'activate':pModal('Attiva il fascicolo dimostrativo','<p>La scheda preliminare diventa una raccolta operativa. Prezzi e piani non sono fissati; non è un acquisto.</p>',pButton('Attiva nella demo','activated'));break;
case'activated':p.active=true;close();render();break;
case'property-new':pModal('Aggiungi un immobile',vField('Indirizzo o nome','p-name')+vField('Città','p-city'),pButton('Aggiungi nella demo','property-save'));break;
case'property-save':{const name=pValue('p-name'),city=pValue('p-city');if(!name||!city){pFormError('Indica nome e città.');break}const prop=pSeed('property-'+pId(),name,city);P.properties.push(prop);pSelect(prop.id);close();go(state.role,state.role==='agency'?'Checklist':'Impianti e memoria');break}
case'request':pModal('Richiesta documenti · anteprima',`<p>Per ${esc(p.name)} mancano:</p>${p.docs.filter(d=>!d.present).map(d=>pRow(d.name,'Destinatario: proprietario o professionista',null)).join('')||pEmpty('Tutti i documenti dell’esempio sono stati ricevuti.')}<p class="tiny">Nessuna email verrà inviata.</p>`,pButton('Predisponi richiesta demo','request-save'));break;
case'request-save':p.requested=p.docs.filter(d=>!d.present).map(d=>d.id);pLog('Richiesta documentale predisposta','Agenzia','Proprietario');close();render();break;
case'receive':{const d=p.docs.find(x=>x.id===id);if(d&&!d.present){d.present=true;d.reviewed=false;pLog('Documento ricevuto: '+d.name,'Proprietario','Agenzia');}render();toast('Ricevuto nella demo. La revisione resta da fare.');break}
case'agency-document':pAgencyDoc(id);break;
case'agency-review':{const d=p.docs.find(x=>x.id===id);d.reviewed=true;pLog('Documento esaminato: '+d.name,'Agenzia','Fascicolo');close();render();break}
case'agency-add':pModal('Aggiungi un documento di esempio',vField('Nome documento','p-name','Scheda impianto elettrico')+'<p>Entra nel fascicolo come ricevuto e da rivedere.</p>',pButton('Aggiungi nella demo','agency-add-save'));break;
case'agency-add-save':{const name=pValue('p-name');if(!name){pFormError('Indica un nome.');break}p.docs.push({id:pId(),name,present:true,reviewed:false,allowed:true,private:false,version:1,source:'Agenzia · caricamento dimostrativo'});close();render();break}
case'dossier-mode':P.selectedDossier=id;render();break;
case'dossier-save':p.dossier=[...document.querySelectorAll('[data-dossier]:checked')].map(x=>x.dataset.dossier);pAction('dossier-preview',[]);break;
case'dossier-preview':pModal('Dossier · '+P.selectedDossier,`<h3>${esc(p.name)}</h3><p>${esc(p.city)} · scheda dell’immobile dimostrativa</p>${P.selectedDossier==='Riservato'?p.docs.filter(d=>p.dossier.includes(d.id)&&d.present&&d.reviewed&&d.allowed&&!d.private).map(d=>pRow(d.name,'v'+d.version+' · selezionato',null)).join('')||pEmpty('Nessun originale selezionato.'):'<p>Anteprima divulgabile: nessun originale del venditore esposto.</p>'}<p class="tiny">Nessun controllo di conformità o accesso reale aperto.</p>`,pButton('Continua con Home Gift →','switch:agency:Home Gift'));break;
case'gift-start':pGiftStart();break;
case'gift-preview':{try{P.pendingGift=pPrepareGift([...document.querySelectorAll('[data-gift-doc]:checked')].map(x=>x.dataset.giftDoc),[...document.querySelectorAll('[data-gift-asset]:checked')].map(x=>x.dataset.giftAsset),pValue('p-email'),$('#p-rights').checked);P.pendingGift.homeName=pValue('p-home-name')||p.name;pModal('Rivedi il manifesto',`<p>Destinatario: ${esc(P.pendingGift.email)}</p>${P.pendingGift.documents.map(d=>pRow(d.name,'Fonte v'+d.version,null)).join('')}${P.pendingGift.assets.map(a=>pRow(a.name,'Scheda con documento fonte incluso',null)).join('')}<p>Esclusi documenti personali, spese e contatti privati.</p>`,pButton('Predisponi invito demo','gift-save'));}catch(e){pFormError(e.message)}break}
case'gift-save':if(P.pendingGift){pCreateGiftHome(P.pendingGift);P.gifts.push(P.pendingGift);pLog('Home Gift predisposta: '+P.pendingGift.documents.length+' documenti','Agenzia','Home');const g=P.pendingGift;P.pendingGift=null;close();render();pGiftDetail(g.id);}break;
case'gift-detail':pGiftDetail(id);break;
case'gift-home':{const g=P.gifts.find(x=>x.id===id);pSelect(g.accepted?g.homeId:g.property);pSwitch('home','Consegne ricevute');close();break}
case'gift-revoke':{const g=P.gifts.find(x=>x.id===id);if(!g.accepted){g.status='Revocato';pLog('Invito Gift revocato','Agenzia','Home',g.property);}close();render();break}
case'gift-inbox':{const g=P.gifts.find(x=>x.id===id);pModal('Home Gift · rivedi la consegna',`<p>${esc(P.brand.agency)} · ${esc(g.status)}</p>${g.documents.map(d=>pRow(d.name,'v'+d.version+' · '+d.source,null)).join('')}<p><strong>${esc(g.homeName||P.properties.find(p=>p.id===g.property)?.name)}</strong> · ${g.assets.length} schede selezionate.</p><p>Accettando aggiungi questa casa alle tue case disponibili, con i soli documenti condivisi. Le altre case restano separate.</p><label class="check"><input id="p-accept" type="checkbox"><span>Ho esaminato la consegna per questa casa nella demo.</span></label>`,!g.accepted&&g.status==='Invito predisposto'?pButton('Accetta nella mia Home','gift-accept:'+id):pButton('Vedi Documenti','switch:home:Documenti'));break}
case'gift-accept':if(!$('#p-accept').checked){pFormError('Esamina e conferma la consegna prima di accettare.');break}try{pAcceptGift(id);close();go('home','Casa');toast('Casa aggiunta alle tue case. Selezione accettata nella demo: ritrovi fonti e schede nella tua Home.');}catch(e){pFormError(e.message)}break;
case'admin-import':pModal('Documento tecnico di esempio',vField('Titolo documento','p-name','Rapporto impianto elettrico')+'<p>Resta interno allo studio finché decidi di pubblicarlo.</p>',pButton('Aggiungi alla memoria','admin-import-save'));break;
case'admin-import-save':{const n=pValue('p-name');if(!n){pFormError('Indica un titolo.');break}p.technical.push({id:pId(),name:n,note:'Nuovo documento · da rivedere',date:'',doc:n,version:1,shared:true});close();render();break}
case'technical':pTechnicalDetail(id);break;
case'technical-edit':{const t=p.technical.find(x=>x.id===id);pModal('Rivedi memoria tecnica',vField('Nota','p-note',t.note)+vField('Data attenzione','p-date',t.date,'date')+'<p>La modifica aggiorna la fonte interna, non le Home automaticamente.</p>',pButton('Salva revisione','technical-save:'+id));break}
case'technical-save':{const t=p.technical.find(x=>x.id===id);t.note=pValue('p-note');t.date=pValue('p-date');t.version++;close();render();break}
case'publish-start':pPublishStart();break;
case'publish-preview':if(!$('#p-rights').checked||!pValue('p-title')){pFormError('Controlla titolo, contenuti e destinatari.');break}P.pendingPublication={technical:pValue('p-tech'),title:pValue('p-title'),note:pValue('p-note'),proposal:$('#p-proposal').checked};pModal('Anteprima pubblicazione',`<p>${esc(p.building)} · ${esc(p.unit)}</p><h3>${esc(P.pendingPublication.title)}</h3><p>${esc(P.pendingPublication.note)}</p><p>${P.pendingPublication.proposal?'Promemoria proposto in Home, non attivato automaticamente.':'Solo informazione comune, nessun dato privato cambiato.'}</p>`,pButton('Pubblica nella demo','publish-save'));break;
case'publish-save':if(P.pendingPublication){const x=P.pendingPublication;try{pPublish(x.technical,x.title,x.note,true,x.proposal);P.pendingPublication=null;close();render();}catch(e){pFormError(e.message)}}break;
case'publication':pPublication(id);break;
case'publication-revoke':P.publications.find(x=>x.id===id).status='Ritirato';pLog('Pubblicazione ritirata','Amministratore','Home');close();render();break;
case'publication-home':{const x=P.publications.find(x=>x.id===id);pSelect(x.property);close();pSwitch('home','Condominio');break}
case'unit-invite':pModal('Collega l’unità alla Home',`<p>${esc(p.building)} · ${esc(p.unit)}</p>${vField('Email proprietario (fittizia)','p-email','','email')}<label class="check"><input id="p-rights" type="checkbox"><span>Ho verificato unità, destinatario e diritti nella demo.</span></label>`,pButton('Predisponi invito','invite-save'));break;
case'invite-save':try{pInvite(pValue('p-email'),$('#p-rights').checked);close();render();}catch(e){pFormError(e.message)}break;
case'invitation':{const i=P.invitations.find(x=>x.id===id);pModal('Invito al condominio',`<p>${esc(p.building)} · ${esc(p.unit)}<br>${esc(i.email)} · ${esc(i.status)}</p>${state.role==='home'?(i.newOwner?'<p>Nuovo proprietario: passi a una Home privata vuota. La memoria del precedente proprietario resta separata.</p>':'<p>Colleghi la vista comune. Lo studio non ottiene accesso ai tuoi documenti personali.</p>')+'<label class="check"><input id="p-accept" type="checkbox"><span>Confermo di esplorare il collegamento di questa unità nella demo.</span></label>':''}`,state.role==='home'&&i.status==='Da accettare'?pButton('Accetta collegamento','invite-accept:'+id):pButton('Vedi invito in Home →','invite-home:'+id));break}
case'invite-home':{const i=P.invitations.find(x=>x.id===id);pSelect(i.property);close();pSwitch('home','Consegne ricevute');break}
case'invite-accept':if(!$('#p-accept').checked){pFormError('Conferma l’unità per proseguire nella demo.');break}try{pAcceptInvitation(id);close();go('home','Condominio');}catch(e){pFormError(e.message)}break;
case'ownership':pModal('Cambio proprietario',vField('Data di efficacia','p-date','2026-11-01','date')+vField('Email nuovo proprietario (fittizia)','p-email','','email')+'<label class="check"><input id="p-rights" type="checkbox"><span>Ho riesaminato i diritti dell’unità. Alla data di efficacia si devono revocare gli accessi precedenti.</span></label><p>La Home privata precedente non viene trasferita.</p>',pButton('Prepara cambio nella demo','ownership-save'));break;
case'ownership-save':if(!pValue('p-date')||!pValidEmail(pValue('p-email'))||!$('#p-rights').checked){pFormError('Controlla data, destinatario e diritti.');break}P.pendingOwnership={property:P.current,date:pValue('p-date'),email:pValue('p-email')};pModal('Cambio programmato · demo','<p>Data di efficacia: '+vDate(P.pendingOwnership.date)+'. Puoi simulare quella data per vedere la revoca della vista comune e il nuovo invito.</p><p>I documenti privati rimangono nella Home precedente.</p>',pButton('Simula data di efficacia','ownership-apply'));break;
case'ownership-apply':{const change=P.pendingOwnership;if(change){pSelect(change.property);P.generations[change.property]=(P.generations[change.property]||0)+1;P.newOwnerPending[change.property]=true;P.links[change.property]={status:'Revocato'};P.invitations.filter(i=>i.property===change.property).forEach(i=>i.status='Revocato');pInvite(change.email,true);pLog('Cambio proprietario: vista comune precedente revocata','Amministratore','Home');P.pendingOwnership=null;}close();render();break}
case'proposal':{const x=P.publications.find(x=>x.id===id);pModal('Un promemoria da decidere',`<p>Fonte: ${esc(P.brand.admin)} · ${esc(x.title)} · v${x.version}</p>${vField('Data del tuo promemoria','p-date','2026-12-01','date')}<p>Non è una scadenza normativa. Nessun impianto privato viene modificato.</p>`,pButton('Aggiungi alle mie attività','proposal-accept:'+id)+pButton('Decidi più avanti','close',true));break}
case'proposal-accept':{const x=P.publications.find(x=>x.id===id),date=pValue('p-date');if(!date){pFormError('Scegli la data del tuo promemoria.');break}const key=x.id+':'+x.version;if(!P.proposalDone.includes(key)){V5.tasks.push({id:pId(),name:x.title,date,object:'',done:false,next:'',origin:'Condominio · '+P.brand.admin});P.proposalDone.push(key);pLog('Proposta comune confermata come promemoria personale','Home','Attività');}close();go('home','Attività');break}
case'issue-start':pIssueStart();break;
case'issue-save':if(P.links[P.activeHome]?.status!=='Collegato'){pFormError('Collega prima la tua unità.');break}if(!pValue('p-title')){pFormError('Descrivi brevemente il problema.');break}P.issues.push({id:pId(),property:P.activeHome,title:pValue('p-title'),detail:pValue('p-note'),status:'Ricevuta',reply:''});pLog('Segnalazione predisposta nella demo','Home','Amministratore');close();render();break;
case'issue':pIssue(id);break;
case'issue-update':{const i=P.issues.find(x=>x.id===id);i.status=pValue('p-issue-status');i.reply=pValue('p-reply');pLog('Stato segnalazione aggiornato: '+i.status,'Amministratore','Home');close();render();break}
case'home-document':vDocument(id);break;
case'team-new':pModal('Aggiungi collaboratore demo',vField('Nome','p-name')+vSelect('Ruolo','p-role',['Responsabile','Collaboratore','Consultazione'],'Collaboratore')+'<p>Nessun invito o accesso reale.</p>',pButton('Aggiungi nella demo','team-save'));break;
case'team-save':if(!pValue('p-name')){pFormError('Indica un nome.');break}P.team[state.role].push({name:pValue('p-name'),role:pValue('p-role')});close();render();break;
case'brand':pModal('Il nome del tuo studio',vField('Nome studio','p-name',P.brand[state.role]),pButton('Salva anteprima','brand-save'));break;
case'brand-save':if(!pValue('p-name')){pFormError('Indica un nome.');break}P.brand[state.role]=pValue('p-name');close();render();break;
case'import-tool':pModal('Import di esempio','<p>Riga proposta: Via del Parco 6 · Bologna.</p><p>Rivedi i dati prima di aggiungere un nuovo fascicolo o edificio. Nessun gestionale connesso.</p>',pButton('Conferma import demo','import-tool-save'));break;
case'import-tool-save':{const found=P.properties.find(x=>x.name==='Via del Parco 6');if(found)pSelect(found.id);else{const n=pSeed('property-'+pId(),'Via del Parco 6','Bologna');P.properties.push(n);pSelect(n.id);}close();go(state.role,state.role==='agency'?'Fascicoli':'Edifici');break}
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!action.startsWith('p:')){if(action.startsWith('select:')&&state.role!=='home'){e.stopImmediatePropagation();pAction('select',action.slice(7).split(':'));}return}e.stopImmediatePropagation();const [a,...args]=action.slice(2).split(':');pAction(a,args);},true);
document.addEventListener('change',e=>{if(e.target.id==='p-property'){pSelect(e.target.value);render();}if(e.target.id==='annual'&&state.role==='admin')pProperty().budget=Number(e.target.value)||0;});
// Match the selected building's scenario when the shared forecast UI is rendered.
const partnerFixture=vFixtureDocument;vFixtureDocument=function(d){const html=partnerFixture(d);return d.gift?html.replace('Fonte: archivio personale · versione 1.','Fonte: '+esc(d.origin)+' · versione '+d.sourceVersion+'.'):html;};
const partnerForecast=forecast;
forecast=function(admin){if(admin)state.budget=pProperty().budget;return partnerForecast(admin);};
route();
